            continue
        path = f"specification.bdd_scenarios[{index}]"
        if not entry.id.valid:
            findings.append(issue("invalid_value", path + ".id"))
        if not entry.steps_is_list or not entry.steps:
            findings.append(issue("invalid_value", path + ".steps"))
